# Referee: the group generated by g (order 13) and the stored Delta-linear automorphism h; order, traces; fixed lattice of an
# order-3 element (Lemma B / Lemma A' equality case): det exactly, and L^c = N_c(L). Exact integer arithmetic.
import numpy as np, sys, time
from math import gcd
from collections import Counter
import sympy
t0=time.time()
D='/home/user/Mathathon/sphere_packing_research/rounds/R5_leech13/'
G8=np.load(D+'G8.npy',allow_pickle=False).astype(np.int64); B=np.load(D+'basisB.npy',allow_pickle=False).astype(np.int64)
hf=np.load(D+'autDelta_gen2.npy',allow_pickle=False); H8=np.rint(8*hf).astype(np.int64); assert (H8==8*hf).all()
qi=np.load(D+'quat_i.npy',allow_pickle=False); Qi=np.rint(8*qi).astype(np.int64)
qj=np.load(D+'quat_j.npy',allow_pickle=False); Qj=np.rint(8*qj).astype(np.int64)
I8=8*np.eye(24,dtype=np.int64)
assert (H8@H8.T==64*np.eye(24,dtype=np.int64)).all()
assert ((B@H8.T@B.T)%64==0).all(), "h does not preserve L"
for X in (Qi,Qj): assert (X@H8==H8@X).all()
def mul(A,Bm):
    C=A@Bm; assert (C%8==0).all(); return C//8
# eta from g
P=[np.eye(24,dtype=np.int64)]
for j in range(1,13): P.append(P[-1]@G8)
leg=[0]+[1 if pow(j,6,13)==1 else -1 for j in range(1,13)]
E8=sum(leg[j]*8**(12-j)*P[j] for j in range(1,13))//8**11
print("h orthogonal, preserves L, commutes with i,j; commutes with eta:",bool((E8@H8==H8@E8).all()),"; commutes with g:",bool((G8@H8==H8@G8).all()))
gens=[G8,H8]; key=lambda M: M.astype(np.int8).tobytes()
elems={key(I8):I8}; frontier=[I8]
while frontier:
    new=[]
    for x in frontier:
        for s in gens:
            y=mul(x,s); k=key(y)
            if k not in elems: elems[k]=y; new.append(y)
    frontier=new
    if len(elems)>20000: sys.exit("group too large")
n=len(elems); print("order of <g,h> =",n)
tr=Counter(int(np.trace(x))//8 if np.trace(x)%8==0 else np.trace(x)/8 for x in elems.values()); print("trace histogram:",dict(sorted(tr.items())))
print("sum of squares of traces / |G| =",sum(t*t*c for t,c in tr.items())/n,"(= dim of commutant)")
allc=all((x@E8==E8@x).all() and (x@Qi==Qi@x).all() and (x@Qj==Qj@x).all() for x in elems.values()); print("all elements commute with eta,i,j:",allc)
# element of order 3
def order(x):
    y=x; k=1
    while not (y==I8).all(): y=mul(y,x); k+=1
    return k
ords=Counter(); c3=None
for x in elems.values():
    o=order(x); ords[o]+=1
    if o==3 and c3 is None: c3=x
print("element orders:",dict(sorted(ords.items())))
if c3 is not None:
    N8=I8+c3+mul(c3,c3)                      # 8*(1+c+c^2)
    V=B@N8.T; assert (V%8==0).all(); V//=8     # images N(b_i), scaled coordinates
    Binv=sympy.Matrix(B.tolist()).inv()
    Cmat=sympy.Matrix(V.tolist())*Binv        # coordinates in the basis B
    assert all(x.q==1 for x in Cmat), "N(b_i) not in L"
    from sympy.matrices.normalforms import smith_normal_form
    snf=smith_normal_form(Cmat,domain=sympy.ZZ); inv=[abs(int(snf[i,i])) for i in range(24) if snf[i,i]!=0]
    print("rank of N(L) =",len(inv),"; Smith invariants of N(L) inside L:",inv," (all 1 <=> N(L) primitive <=> N(L)=L^c)")
    # basis of N(L): integer row reduction (HNF) of V
    rows=[[int(x) for x in r] for r in V.tolist()]; basis=[]; col=0
    while col<24 and rows:
        rows=[r for r in rows if any(r)]
        piv=[r for r in rows if r[col]!=0]
        if not piv: col+=1; continue
        while len(piv)>1:
            piv.sort(key=lambda r: abs(r[col])); p0=piv[0]
            for r in piv[1:]:
                q=r[col]//p0[col]
                for k in range(24): r[k]-=q*p0[k]
            piv=[r for r in piv if r[col]!=0]
        basis.append(piv[0][:]); 
        for k in range(24): piv[0][k]=0
        col+=1
    Mb=sympy.Matrix(basis); Gr=Mb*Mb.T; d=Gr.det(); r=len(basis)
    print("rank",r,"; det of fixed lattice (unimodular normalisation) =",sympy.Rational(d,8**r),"; 3^8 =",3**8, "; R_U = 3^8/det =",sympy.Rational(3**8*8**r,d))
    mn=min(int(Gr[i,i]) for i in range(r))//8
    print("smallest basis-vector norm in fixed lattice:",mn)
print("time %.1fs"%(time.time()-t0))
